begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.uid(n integer)returns uuid language sql immutable as $$select('19150000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at,raw_app_meta_data,raw_user_meta_data)
select pg_temp.uid(n),'authenticated','authenticated','media-s191-'||n||'@veyocast.test','test',now(),now(),now(),'{}','{}'from generate_series(1,4)n;
insert into public.profiles(id,display_name)select pg_temp.uid(n),'Media editor '||n from generate_series(1,4)n;
insert into public.tenants(id,name,slug)values(pg_temp.uid(10),'Media A','media-s191-a'),(pg_temp.uid(11),'Media B','media-s191-b');
insert into public.tenant_memberships(tenant_id,user_id,role)values(pg_temp.uid(10),pg_temp.uid(1),'tenant_owner'),(pg_temp.uid(11),pg_temp.uid(2),'tenant_owner'),(pg_temp.uid(10),pg_temp.uid(3),'tenant_viewer'),(pg_temp.uid(10),pg_temp.uid(4),'tenant_owner');
insert into public.media_assets(id,tenant_id,kind,title,original_file_name,mime_type,status,storage_path,file_size_bytes,checksum_sha256,width,height)
select pg_temp.uid(n),pg_temp.uid(case when n=21 then 11 else 10 end),'image','Original photo '||n,'photo.webp','image/webp','ready',
'tenants/'||pg_temp.uid(case when n=21 then 11 else 10 end)||'/assets/'||pg_temp.uid(n)||'/original.webp',2048,repeat('a',64),1920,1080 from generate_series(20,21)n;
insert into public.media_folders(id,tenant_id,name,created_by)values(pg_temp.uid(30),pg_temp.uid(10),'Clubcontent',pg_temp.uid(1)),(pg_temp.uid(31),pg_temp.uid(11),'Foreign folder',pg_temp.uid(2));
insert into public.media_asset_favorites(tenant_id,media_asset_id,user_id)values(pg_temp.uid(10),pg_temp.uid(20),pg_temp.uid(4));
create temporary table media_before as select updated_at,storage_path,checksum_sha256,file_size_bytes from public.media_assets where id=pg_temp.uid(20);
create temporary table results(name text primary key,value jsonb);grant all on results,media_before to authenticated;
create function pg_temp.payload()returns jsonb language sql immutable as $$select jsonb_build_object('title','Saved club photo','folderId',pg_temp.uid(30),'tags','["Club","club","Jeugd"]'::jsonb,'collections','["Sponsorbeelden"]'::jsonb,'favorite',true)$$;
create function pg_temp.save(p_key integer,p_payload jsonb default null,p_expected timestamptz default null)returns jsonb language sql as $$select public.save_media_metadata_v1(pg_temp.uid(10),pg_temp.uid(20),coalesce(p_expected,(select updated_at from public.media_assets where id=pg_temp.uid(20))),coalesce(p_payload,pg_temp.payload()),pg_temp.uid(p_key))$$;
select ok(not has_function_privilege('anon','public.save_media_metadata_v1(uuid,uuid,timestamptz,jsonb,uuid)','EXECUTE'),'anonymous cannot save metadata');
select ok(not has_function_privilege('authenticated','public.mutate_media_organization_before_metadata_v1(uuid,text,jsonb,uuid)','EXECUTE'),'browser cannot bypass parent lock wrapper');
select ok(not has_function_privilege('authenticated','private.touch_media_membership_clock_v1()','EXECUTE'),'membership clock stays private');
set local role authenticated;select set_config('request.jwt.claim.sub',pg_temp.uid(1)::text,true);
select throws_ok($$select pg_temp.save(100,pg_temp.payload()||'{"favorite":"true"}')$$,'23514',null,'string boolean cannot mutate favorite');
select throws_ok($$select pg_temp.save(101,pg_temp.payload()||'{"rawUrl":"https://example.invalid"}')$$,'23514',null,'unknown payload keys fail closed');
select throws_ok($$select pg_temp.save(102,pg_temp.payload()-'folderId')$$,'23514',null,'partial modal payload cannot drop a field silently');
select throws_ok($$select pg_temp.save(103,pg_temp.payload()||'{"tags":[null]}')$$,'23514',null,'non-string tag rejected');
select throws_ok($$select pg_temp.save(104,pg_temp.payload()||jsonb_build_object('tags',jsonb_build_array(repeat('x',49))))$$,'23514',null,'original 48-character tag limit retained');
select throws_ok($$select pg_temp.save(105,pg_temp.payload()||jsonb_build_object('collections',jsonb_build_array(repeat('x',81))))$$,'23514',null,'original 80-character collection limit retained');
select throws_ok($$select pg_temp.save(106,pg_temp.payload()||jsonb_build_object('tags',(select jsonb_agg('tag'||n)from generate_series(1,21)n)))$$,'23514',null,'label count bounded before writing');
select throws_ok($$select pg_temp.save(107,pg_temp.payload()||jsonb_build_object('folderId',pg_temp.uid(31)))$$,'23514',null,'foreign tenant folder rejected atomically');
select is((select title from public.media_assets where id=pg_temp.uid(20)),'Original photo 20','rejected edits preserve original title');
select is((select count(*)from public.media_tags where tenant_id=pg_temp.uid(10)),0::bigint,'rejected folder creates no partial tags');
select throws_ok($$select public.save_media_metadata_v1(pg_temp.uid(10),pg_temp.uid(21),now(),pg_temp.payload(),pg_temp.uid(108))$$,'P0002',null,'foreign tenant asset unavailable');
insert into results values('saved',pg_temp.save(110,null,(select updated_at from media_before)));
select is((select value->>'outcome'from results where name='saved'),'applied','one complete metadata edit receives real applied receipt');
select is((select title from public.media_assets where id=pg_temp.uid(20)),'Saved club photo','actual title persists');
select is((select folder_id from public.media_assets where id=pg_temp.uid(20)),pg_temp.uid(30),'actual tenant folder persists');
select is((select count(*)from public.media_asset_tags where media_asset_id=pg_temp.uid(20)),2::bigint,'case-insensitive duplicate tag labels deduplicated');
select is((select count(*)from public.media_collection_items where media_asset_id=pg_temp.uid(20)),1::bigint,'collection membership persists atomically');
select is((select count(*)from public.media_asset_favorites where media_asset_id=pg_temp.uid(20)),1::bigint,'favorite RLS exposes only the current actor membership');
reset role;
select is((select count(*)from public.media_asset_favorites where media_asset_id=pg_temp.uid(20)),2::bigint,'privileged readback proves another actor favorite preserved');
set local role authenticated;
select ok((select updated_at>(select updated_at from media_before)from public.media_assets where id=pg_temp.uid(20)),'metadata clock advances even within one SQL transaction');
select is(pg_temp.save(110,null,(select updated_at from media_before)),(select value from results where name='saved'),'retry returns frozen successful receipt before stale check');
select is((select updated_at::text from public.media_assets where id=pg_temp.uid(20)),(select(value->>'actualUpdatedAt')::timestamptz::text from results where name='saved'),'replay does not advance metadata clock');
select throws_ok($$select pg_temp.save(110,pg_temp.payload()||'{"title":"Changed request"}',(select updated_at from media_before))$$,'23505',null,'reusing key for different edit rejected');
insert into results values('conflict',pg_temp.save(111,pg_temp.payload()||'{"title":"Stale edit"}',(select updated_at from media_before)));
select is((select value->>'outcome'from results where name='conflict'),'conflict','second authoring session receives conflict');
select is((select title from public.media_assets where id=pg_temp.uid(20)),'Saved club photo','stale save cannot overwrite current metadata');
select is((select row(storage_path,checksum_sha256,file_size_bytes)::text from public.media_assets where id=pg_temp.uid(20)),(select row(storage_path,checksum_sha256,file_size_bytes)::text from media_before),'original immutable bytes identity unchanged');
select lives_ok($$select pg_temp.save(112,pg_temp.payload()||'{"favorite":false,"tags":[],"collections":[],"folderId":null}')$$,'empty labels and root folder save as explicit metadata choices');
select is((select count(*)from public.media_asset_tags where media_asset_id=pg_temp.uid(20)),0::bigint,'explicit empty tag list removes memberships');
select is((select count(*)from public.media_collection_items where media_asset_id=pg_temp.uid(20)),0::bigint,'explicit empty collection list removes memberships');
select is((select count(*)from public.media_asset_favorites where media_asset_id=pg_temp.uid(20)),0::bigint,'unfavorite removes current actor membership');
reset role;
select is((select count(*)from public.media_asset_favorites where media_asset_id=pg_temp.uid(20)),1::bigint,'privileged readback proves unfavorite retained the other actor membership');
set local role authenticated;
insert into results select 'before-old-command',jsonb_build_object('updatedAt',updated_at)from public.media_assets where id=pg_temp.uid(20);
select lives_ok($$select public.mutate_media_organization_v1(pg_temp.uid(10),'set_favorite',jsonb_build_object('assetId',pg_temp.uid(20),'favorite',true),pg_temp.uid(113))$$,'existing favorite command remains usable through parent-first wrapper');
select is(pg_temp.save(114,null,(select(value->>'updatedAt')::timestamptz from results where name='before-old-command'))->>'outcome','conflict','older organization command invalidates an open modal token');
-- Displayed label names and active collection choices participate in CAS.
select lives_ok($$select pg_temp.save(120)$$,'prepare real label and collection memberships');
insert into results select 'before-label-rename',jsonb_build_object('updatedAt',updated_at)from public.media_assets where id=pg_temp.uid(20);
select is(public.mutate_media_organization_v1(pg_temp.uid(10),'update_tag',jsonb_build_object('tagId',(select id from public.media_tags where tenant_id=pg_temp.uid(10)and lower(name)='club'),'expectedRevision',0,'name','Senioren'),pg_temp.uid(121))->>'outcome','applied','existing tag rename command actually changes the tag');
select is(pg_temp.save(122,null,(select(value->>'updatedAt')::timestamptz from results where name='before-label-rename'))->>'outcome','conflict','tag rename invalidates the full modal token');
select is((select count(*)from public.media_tags where tenant_id=pg_temp.uid(10)and lower(name)='club'),0::bigint,'stale save cannot recreate the previous tag name');
insert into results select 'before-collection-rename',jsonb_build_object('updatedAt',updated_at)from public.media_assets where id=pg_temp.uid(20);
select is(public.mutate_media_collection_v1(pg_temp.uid(10),(select id from public.media_collections where tenant_id=pg_temp.uid(10)and lower(name)='sponsorbeelden'),0,'update','{"name":"Wedstrijdfoto’s"}',pg_temp.uid(123))->>'outcome','applied','existing collection rename command remains usable');
select is(pg_temp.save(124,null,(select(value->>'updatedAt')::timestamptz from results where name='before-collection-rename'))->>'outcome','conflict','collection rename invalidates the full modal token');
insert into results select 'before-collection-archive',jsonb_build_object('updatedAt',updated_at)from public.media_assets where id=pg_temp.uid(20);
select is(public.mutate_media_collection_v1(pg_temp.uid(10),(select id from public.media_collections where tenant_id=pg_temp.uid(10)and name='Wedstrijdfoto’s'),1,'archive','{}',pg_temp.uid(125))->>'outcome','applied','existing collection archive command remains usable');
select is(pg_temp.save(126,null,(select(value->>'updatedAt')::timestamptz from results where name='before-collection-archive'))->>'outcome','conflict','collection archive invalidates the full modal token');
select ok(not has_function_privilege('authenticated','public.mutate_media_collection_before_metadata_v1(uuid,uuid,bigint,text,jsonb,uuid)','EXECUTE'),'collection writer cannot bypass tenant serialization');
select ok(not has_function_privilege('authenticated','private.lock_media_metadata_v1(uuid)','EXECUTE'),'browser cannot hold or bypass private metadata lock');
select ok(not has_table_privilege(role_name,table_name,'INSERT,UPDATE,DELETE'),role_name||' cannot bypass command locking on '||table_name)
from unnest(array['authenticated','service_role'])role_name cross join unnest(array['public.media_folders','public.media_tags','public.media_collections','public.media_asset_tags','public.media_collection_items','public.media_asset_favorites'])table_name;
select throws_ok($$delete from public.media_asset_tags where media_asset_id=pg_temp.uid(20)$$,'42501','permission denied for table media_asset_tags','direct child-first deletion fails before acquiring any row lock');
select set_config('request.jwt.claim.sub',pg_temp.uid(3)::text,true);
select throws_ok($$select pg_temp.save(115)$$,'42501',null,'viewer cannot edit shared media metadata');
select lives_ok($$select public.mutate_media_organization_v1(pg_temp.uid(10),'set_favorite',jsonb_build_object('assetId',pg_temp.uid(20),'favorite',true),pg_temp.uid(116))$$,'viewer retains permission to its own existing private favorites');
select set_config('request.jwt.claim.sub',pg_temp.uid(2)::text,true);
select throws_ok($$select pg_temp.save(117)$$,'42501',null,'tenant B cannot invoke tenant A metadata command');
select is((select count(*)from public.media_assets where id=pg_temp.uid(20)),0::bigint,'tenant B cannot read tenant A asset');
select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select pg_temp.save(118)$$,'42501',null,'missing actor rejected before accessing metadata');
reset role;
select *from finish();rollback;
